  const style=document.createElement('style');style.id='nexus-cloud-style';style.textContent='__NEXUS_CLOUD_CSS__';document.head.append(style);
  let nativeSelection=[],authorizationPending=false;const recoverySelection=new Set();let recoveryFocusKey='',recoveryPreferredId='';let notificationState={attempts:[]},statusLoaded=false,notificationHost=null,readNotice=null,dismissedAttempt='',lastNotificationSignature='',restoreResult=null,restoreTimer=null,seenRestoreResult='',operationHost=null,ordinaryNotice='',journalPlan=null,scopedPreparing=false,recoveryTransition=null,recoveryRevision=0,refreshRevision=0;
  const nativeCaption=['win32','darwin'].includes(window.electron?.platform);
