  function applyArtwork(){if(!body)return;const byKey=new Map(snapshot.games.map(g=>[g.key,g]));for(const img of body.querySelectorAll('img[data-art-key]')){const g=byKey.get(img.dataset.artKey);if(!g)continue;const url=candidates(g)[0];if(url){img.hidden=false;if(img.getAttribute('src')!==url)img.src=url;}else{img.hidden=true;img.removeAttribute('src');}}}
  function enrichVisible(){if(!body)return;applyArtwork();if(typeof window.electron?.getGameAssets!=='function')return;const keys=new Set([...body.querySelectorAll('img[data-art-key]')].map(img=>img.dataset.artKey));for(const g of snapshot.games){if(!keys.has(g.key)||g.shop==='custom'||g.art?.customCover)continue;const signature=artSignature(g),cache=artwork.get(g.key);if(queuedArt.has(g.key)||cache?.signature===signature&&Date.now()-cache.at<(cache.failed?30000:900000))continue;queuedArt.add(g.key);artQueue.push({game:g,signature,token:epoch});}pumpArt();}
  function pumpArt(){while(screen&&artWorkers<3&&artQueue.length){const task=artQueue.shift();if(task.token!==epoch){queuedArt.delete(task.game.key);continue;}artWorkers++;const {game:g,signature,token}=task,identity=g.catalogueGame||g;Promise.resolve().then(()=>window.electron.getGameAssets(String(identity.objectId??g.key.split(':')[1]),identity.shop||g.shop||g.key.split(':')[0],{artworkIdentity:{shop:g.shop||g.key.split(':')[0],objectId:String(g.objectId??g.key.split(':')[1])}})).then(assets=>{if(token!==epoch||!screen)return;artwork.set(g.key,{signature,at:Date.now(),covers:[assets?.coverImageUrl,assets?.libraryImageUrl],failed:false});while(artwork.size>300)artwork.delete(artwork.keys().next().value);applyArtwork();},()=>{if(token===epoch&&screen)artwork.set(g.key,{signature,at:Date.now(),covers:[],failed:true});}).finally(()=>{artWorkers--;if(token===epoch)queuedArt.delete(g.key);pumpArt();});}}
  const depth=name=>'<span class="nc-depth-icon">'+icon(name)+'</span>';
  function entrance(data=false){if(!body)return;const nodes=data?[...body.querySelectorAll('.nc-metric,.nc-recovery-grid .nc-game')]:[...body.querySelectorAll('.nc-top,.nc-nav,.nc-hero-copy,.nc-dashboard>.nc-main>.nc-card,.nc-dashboard>.nc-side>.nc-card')];nodes.forEach((el,i)=>el.animate([{opacity:0,transform:'translateY('+(data?8:14)+'px)'},{opacity:1,transform:'translateY(0)'}],{duration:data?380:520,delay:Math.min(i*(data?35:45),220),easing:'cubic-bezier(.16,1,.3,1)',fill:'backwards'}));if(data)for(const el of body.querySelectorAll('[data-count]')){const total=Number(el.dataset.count);if(!Number.isFinite(total)||!total)continue;const start=performance.now(),token=epoch;const tick=now=>{if(token!==epoch||!el.isConnected||Number(el.dataset.count)!==total)return;const t=Math.min(1,(now-start)/480);el.textContent=fmt(Math.round(total*(1-(1-t)**3)));if(t<1)requestAnimationFrame(tick);};requestAnimationFrame(tick);}}
  let frame=null,header=null,panel=null,body=null,covered=[],oldFocus=null,route='',view='overview',detail='',snapshot={settings:{},provider:{},games:[],transfers:[],activity:[]},busy=0,poll=null,refreshing=null,notice='',diagnostic='',query='',filter='all',sort='recent',limit=30,dialog=null,restorePlan=null,epoch=0,knownTransferStates=new Map(),initialLoad=false;
  const fmt=n=>new Intl.NumberFormat(language()).format(Number(n)||0),date=v=>v&&Number.isFinite(new Date(v).getTime())?new Intl.DateTimeFormat(language(),{dateStyle:'medium',timeStyle:'short'}).format(new Date(v)):tr('Never');
  const bytes=n=>{if(n===undefined||n===null)return '—';const v=Math.max(0,Number(n)||0),i=Math.min(4,Math.floor(Math.log2(Math.max(1,v))/10));return new Intl.NumberFormat(language(),{maximumFractionDigits:i?1:0}).format(v/1024**i)+' '+['B','KiB','MiB','GiB','TiB'][i];};
  const points=g=>Array.isArray(g.points)?g.points:[],local=p=>p.local===true||p.location==='local'||p.localAvailable===true,cloud=p=>p.cloud===true||p.uploaded===true||p.status==='uploaded',last=g=>points(g).reduce((n,p)=>Math.max(n,new Date(p.createdAt||p.time||0).getTime()||0),0),eligible=g=>['detected','found','available'].includes(g.saveStatus)||g.hasSaves===true;
  const button=(text,action,attrs='',disabled=false,primary=false)=>'<button type="button" class="button button--'+(primary?'primary':'outline')+' nc-action-'+action+'" data-cloud-action="'+action+'" '+attrs+(disabled?' disabled':'')+'>'+({scan:icon('scan'),backup:icon('upload'),openRecovery:icon('cloud'),close:icon('back')}[action]||'')+'<span>'+ht(text)+'</span></button>';
