  // Resolve semantic button colors with motion disabled on an invisible theme probe.
  // Reading an animating background can choose a stale foreground during language/state updates.
  function colorButtons(){if(!body)return;for(const button of body.querySelectorAll('.button'))button.style.setProperty('color',button.classList.contains('button--primary')?'#062820':'#edf5f5','important');}
  function render(){if(!frame)return;if(view==='recovery'&&notice==='Operation completed')notice='';window.__nexusI18n?.controls?.(body,panel);frame.dir=language()==='ar'?'rtl':'ltr';screen.dir=frame.dir;screen.lang=language();header.dir=frame.dir;frame.lang=language();patch(header,'<div class="nc-wordmark"><img src="'+LOGO+'" alt="Hydra Nexus"><div><strong>'+esc('HYDRA NEXUS')+'</strong><span>Nexus Cloud <small class="nc-beta" dir="ltr" title="'+ht('Beta')+'">'+esc('BETA')+'</small></span></div></div>'+(nativeCaption?'':'<div class="nc-window-controls" dir="ltr"><button data-cloud-action="minimizeWindow" aria-label="'+ht('Minimize window')+'">'+icon('minus')+'</button><button data-cloud-action="maximizeWindow" aria-label="'+ht('Maximize window')+'">'+icon('window')+'</button><button data-cloud-action="closeWindow" aria-label="'+ht('Close window')+'">'+icon('close')+'</button></div>'));const names={overview:'Overview',library:'Backup Library',transfers:'Transfer Manager',settings:'Cloud Settings',detail:'Backup Library',recovery:'Restore from cloud',backup:'Back up now',sources:'Save sources',batch:'Back up all games'};patch(body,'<div class="nc-return-row">'+button('Back to Hydra','close')+'</div><div class="nc-top"><div><h1>'+ht(names[view])+'</h1></div>'+(view==='recovery'?'':'<div class="nc-actions">'+button('Scan saves','scan','',!!busy)+button('Restore from cloud','openRecovery','',false,true)+'</div>')+'</div><nav class="nc-nav" aria-label="Nexus Cloud">'+Object.entries(names).filter(([k])=>!['detail','recovery','backup','sources','batch'].includes(k)).map(([k,label])=>'<button class="button button--'+(view===k||view==='detail'&&k==='library'?'primary':'outline')+'" data-cloud-action="view" data-view="'+k+'" aria-current="'+(view===k?'page':'false')+'">'+icon(({overview:'home',library:'folder',transfers:'transfer',settings:'settings'})[k])+ht(label)+'</button>').join('')+'</nav><div class="nc-notice" data-nc-key="notice" role="status" '+(!notice?'hidden':'')+'>'+ht(notice)+(diagnostic?'<details><summary>'+ht('Diagnostic details')+'</summary><pre>'+esc(diagnostic)+'</pre></details>':'')+'</div>'+(!snapshot.settings.enabled?'<section class="nc-card nc-onboarding" data-nc-key="onboarding">'+icon('cloud')+'<div><h2>'+ht('Enable Nexus Cloud')+'</h2><p class="nc-muted">'+ht('You control automatic backups and uploads. Both are off until you enable them.')+'</p></div>'+button('Enable Nexus Cloud','enable','',!!busy,true)+'</section>':'')+recoveryWarning()+(view==='overview'?dashboard():view==='library'?library():view==='detail'?gameDetails():view==='recovery'?recoveryView():view==='backup'?backupView():view==='sources'?sourceView():view==='batch'?batchView():view==='settings'?'<div class="nc-settings-grid">'+providerCard()+quickSettings(true)+encryptionCard()+'<section class="nc-card">'+heading('Cloud Provider')+'<div class="nc-actions">'+button('Refresh cloud backups','refreshCloud','',!snapshot.provider.connected)+button('Disconnect','disconnect','',!snapshot.provider.connected&&!snapshot.provider.provider)+'</div><p class="nc-muted">'+ht('Disconnecting does not delete your cloud backups.')+'</p></section></div>':'<section class="nc-card">'+heading('Transfer Manager')+transferList()+'</section>'));window.__nexusI18n?.buttons?.(body);window.__nexusI18n?.buttons?.(header);colorButtons();enrichVisible();renderNotifications();}
  function beginRecoveryTransition(phase){recoveryRevision++;scopedPreparing=false;const transition=recoveryTransition={phase,cancelled:false};snapshot.recovery={...(phase==='scanning'?{}:snapshot.recovery),phase,games:phase==='scanning'?[]:snapshot.recovery?.games||[],items:[],current:phase==='preparing'?snapshot.recovery?.games?.find(g=>recoverySelection.has(g.id))?.title||null:null,completed:0,total:phase==='preparing'?recoverySelection.size:0,error:null};return transition;}
  function finishRecoveryTransition(transition){if(recoveryTransition===transition){recoveryTransition=null;recoveryRevision++;}}
  async function refresh(){if(refreshing){const revision=refreshRevision;return refreshing.then(()=>{if(frame&&(initialLoad||revision!==recoveryRevision))return refresh();});}const token=epoch,revision=refreshRevision=recoveryRevision;refreshing=api.request('cloudSnapshot').then(v=>{if(frame&&token===epoch&&revision===recoveryRevision){normalize(v);const state=snapshot.recovery;if(view==='recovery'&&state?.phase==='select'&&state.scopeKey&&state.games.length===1&&!scopedPreparing){scopedPreparing=true;recoverySelection.clear();recoverySelection.add(state.games[0].id);const scope=state.scopeKey;setTimeout(()=>{if(!scopedPreparing||view!=='recovery'||snapshot.recovery?.scopeKey!==scope)return;scopedPreparing=false;void action('recoveryPrepare');},0);}if(initialLoad){initialLoad=false;notice='';render();entrance(true);}else render();}}).catch(e=>{if(frame&&token===epoch&&revision===recoveryRevision){notice='Operation failed. Your saved backups have been kept.';diagnostic=e.message;render();}}).finally(()=>refreshing=null);return refreshing;}
